-- Generated by scripts/advisories.mjs from advisories/**/*.json. Do not edit by hand.
-- Public, sourced advisories. review_status stays 'unreviewed' until a maintainer reproduces the issue.
insert into public.advisories (id, summary, details, severity, ecosystem, package, affected, aliases, "references", published, modified, status, review_status, body)
values ('ATLS-2025-0001', 'mcp-remote: OS command injection from a malicious MCP server''s OAuth authorization_endpoint', 'mcp-remote passed the authorization_endpoint URL returned by a remote MCP server during the OAuth flow to a function that opens URLs on the local machine. A malicious or compromised MCP server could craft that value so that connecting to it ran arbitrary OS commands on the developer''s machine. Upgrade mcp-remote to 0.1.16 or later and only connect to MCP servers you trust.', 'critical', 'npm', 'mcp-remote',
  '[{"package":{"ecosystem":"npm","name":"mcp-remote"},"ranges":[{"type":"SEMVER","events":[{"introduced":"0.0.5"},{"fixed":"0.1.16"}]}]}]'::jsonb, array['CVE-2025-6514']::text[], '[{"type":"ADVISORY","url":"https://nvd.nist.gov/vuln/detail/CVE-2025-6514"},{"type":"WEB","url":"https://www.wiz.io/vulnerability-database/cve/cve-2025-6514"}]'::jsonb,
  '2026-10-11T00:00:00Z', '2026-10-11T00:00:00Z', 'published', 'unreviewed', '{"schema_version":"1.6.0","id":"ATLS-2025-0001","aliases":["CVE-2025-6514"],"summary":"mcp-remote: OS command injection from a malicious MCP server''s OAuth authorization_endpoint","details":"mcp-remote passed the authorization_endpoint URL returned by a remote MCP server during the OAuth flow to a function that opens URLs on the local machine. A malicious or compromised MCP server could craft that value so that connecting to it ran arbitrary OS commands on the developer''s machine. Upgrade mcp-remote to 0.1.16 or later and only connect to MCP servers you trust.","severity_label":"critical","affected":[{"package":{"ecosystem":"npm","name":"mcp-remote"},"ranges":[{"type":"SEMVER","events":[{"introduced":"0.0.5"},{"fixed":"0.1.16"}]}]}],"references":[{"type":"ADVISORY","url":"https://nvd.nist.gov/vuln/detail/CVE-2025-6514"},{"type":"WEB","url":"https://www.wiz.io/vulnerability-database/cve/cve-2025-6514"}],"published":"2026-10-11T00:00:00Z","modified":"2026-10-11T00:00:00Z","database_specific":{"atls_review":"unreviewed","source":"Public CVE record; not independently reproduced by Atls."}}'::jsonb)
