insert into public.advisories (id, summary, details, severity, ecosystem, package, affected, aliases, "references", published, modified, status, review_status, body)
values ('ATLS-2025-0004', 'MCP filesystem server: path prefix collision bypasses the allowed-directory check', 'In @modelcontextprotocol/server-filesystem before 0.6.4 (or 2025.7.01), the allowed-directory check compared path prefixes as strings, so a path such as /data/allowed_evil passed a check for /data/allowed. This let callers reach files outside the configured directories. Upgrade to 0.6.4 / 2025.7.01 or later.', 'high', 'npm', '@modelcontextprotocol/server-filesystem',
  '[{"package":{"ecosystem":"npm","name":"@modelcontextprotocol/server-filesystem"},"ranges":[{"type":"SEMVER","events":[{"introduced":"0"},{"fixed":"0.6.4"}]}]}]'::jsonb, array['CVE-2025-53110']::text[], '[{"type":"ADVISORY","url":"https://nvd.nist.gov/vuln/detail/CVE-2025-53110"},{"type":"WEB","url":"https://v2.cvefeed.io/vuln/detail/CVE-2025-53110"}]'::jsonb,
  '2026-10-11T00:00:00Z', '2026-10-11T00:00:00Z', 'published', 'unreviewed', '{"schema_version":"1.6.0","id":"ATLS-2025-0004","aliases":["CVE-2025-53110"],"summary":"MCP filesystem server: path prefix collision bypasses the allowed-directory check","details":"In @modelcontextprotocol/server-filesystem before 0.6.4 (or 2025.7.01), the allowed-directory check compared path prefixes as strings, so a path such as /data/allowed_evil passed a check for /data/allowed. This let callers reach files outside the configured directories. Upgrade to 0.6.4 / 2025.7.01 or later.","severity_label":"high","affected":[{"package":{"ecosystem":"npm","name":"@modelcontextprotocol/server-filesystem"},"ranges":[{"type":"SEMVER","events":[{"introduced":"0"},{"fixed":"0.6.4"}]}]}],"references":[{"type":"ADVISORY","url":"https://nvd.nist.gov/vuln/detail/CVE-2025-53110"},{"type":"WEB","url":"https://v2.cvefeed.io/vuln/detail/CVE-2025-53110"}],"published":"2026-10-11T00:00:00Z","modified":"2026-10-11T00:00:00Z","database_specific":{"atls_review":"unreviewed","fixed_also_in":"2025.7.01","source":"Public CVE record; not independently reproduced by Atls."}}'::jsonb)
